{
  "angles": [
    {
      "angle": "Bitcoin's security doesn't make holding it hands-off: self-custody can scare people, and intermediaries can get hacked.",
      "moments": [
        "c49cd35dfd86efb624e0",
        "f91c4a6b4a5ea9388c32",
        "876662b7dc4e961d47e1"
      ],
      "hook": "c49cd35dfd86efb624e0",
      "support": {
        "c49cd35dfd86efb624e0": "Holding Bitcoin requires active participation.",
        "f91c4a6b4a5ea9388c32": "Self-custody is increasingly frightening to people.",
        "876662b7dc4e961d47e1": "Distinguishes intermediary hacks from Bitcoin's security."
      }
    },
    {
      "angle": "Bitcoin can be considered deeply undervalued while the market still treats it as risky and swings between enthusiasm and rejection.",
      "moments": [
        "b0b787f8a62d97d81dbb",
        "01154f025a00f40132a7",
        "0c751a33022013fb3086"
      ],
      "hook": "b0b787f8a62d97d81dbb",
      "support": {
        "b0b787f8a62d97d81dbb": "Makes the undervaluation case.",
        "01154f025a00f40132a7": "Explains risk treatment and pressure from higher rates.",
        "0c751a33022013fb3086": "Describes enthusiasm at tops and rejection at bottoms."
      }
    },
    {
      "angle": "Bitcoin offers an alternative to government money whose supply others can print, but that alternative has to stay decentralized and secure.",
      "moments": [
        "128b99b7a2487f58d3ba",
        "863cc95ab7c5e0c11482",
        "5e38ec62aa36eae80132"
      ],
      "hook": "128b99b7a2487f58d3ba",
      "support": {
        "128b99b7a2487f58d3ba": "Identifies purchasing-power loss from others printing money.",
        "863cc95ab7c5e0c11482": "Frames Bitcoin as a choice beyond government money.",
        "5e38ec62aa36eae80132": "Names decentralization and security as necessary conditions."
      }
    }
  ]
}
